// Get all the data we need in a single query
allData = from(bucket: "signals_db/default_signals_retention")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "StrategySignal")
  |> filter(fn: (r) => contains(value: r.strategy, set: ${Strategy:json}))
  |> filter(fn: (r) => r._field == "signal" or r._field == "bid" or r._field == "ask")
  // Aggregate early to reduce data points being processed
  |> aggregateWindow(every: $__interval, fn: last, createEmpty: false)

// Separate signals from bid/ask
signalData = allData
  |> filter(fn: (r) => r._field == "signal")
  |> drop(columns: ["_field"])
  |> rename(columns: {_value: "signal"})

// Process current mid price
midData = allData
  |> filter(fn: (r) => r._field == "bid" or r._field == "ask")
  |> pivot(rowKey: ["_time", "strategy"], columnKey: ["_field"], valueColumn: "_value")
  |> map(fn: (r) => ({
       _time: r._time,
       strategy: r.strategy,
       current_mid: (r.bid + r.ask) / 2.0,
       bid: r.bid,
       ask: r.ask
     }))

// Get future mid price using duplicate of midData and timeShift
futureMidData = midData
  |> timeShift(duration: duration(v: "-${walkahead}"))
  |> rename(columns: {
      current_mid: "future_mid",
      bid: "future_bid", 
      ask: "future_ask"
    })

// Join signals and current mid - keep all fields
signalAndMid = join(
  tables: {sig: signalData, mid: midData},
  on: ["_time", "strategy"]
)

// Join with future mid and calculate - keep all component fields
componentResult = join(
  tables: {sm: signalAndMid, fm: futureMidData},
  on: ["_time", "strategy"]
)
  |> map(fn: (r) => {
      signal_mid_diff = r.signal - r.current_mid

      // Calculate the incremental change
      incremental_walkahead = if signal_mid_diff == 0.0
                             then 0.0
                             else if signal_mid_diff > 0.0 
                                   then r.future_mid - r.current_mid 
                                   else r.current_mid - r.future_mid

      return {
        _time: r._time,
        strategy: r.strategy,
        // Component fields
        signal: r.signal,
        current_mid: r.current_mid,
        future_mid: r.future_mid,
        signal_mid_diff: signal_mid_diff,
        // The calculated field (pre-cumsum)
        incremental_walkahead: incremental_walkahead,
        // This will become the cumulative sum
        varad_walkahead: incremental_walkahead
      }
  })
  |> group(columns: ["strategy"])
  |> sort(columns: ["_time"])

// Apply cumulative sum - creates a copy of the table with cumulative sum
cumulativeResult = componentResult
  |> cumulativeSum(columns: ["varad_walkahead"])
  |> set(key: "walkahead", value: "${walkahead}")

// Final result is the cumulative result
cumulativeResult

// Optimized Walk-Forward Analysis Query

// --- Step 1: Prepare a unified stream of CURRENT data (signal and mid-price) ---
// This avoids the first expensive join by pivoting all necessary fields into one table.
currentData = from(bucket: "signals_db/default_signals_retention")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "StrategySignal")
  |> filter(fn: (r) => contains(value: r.strategy, set: ${Strategy:json}))
  |> filter(fn: (r) => r._field == "signal" or r._field == "bid" or r._field == "ask")
  // Aggregate early to reduce the number of rows before the expensive pivot
  |> aggregateWindow(every: $__interval, fn: last, createEmpty: false)
  // CORE OPTIMIZATION: Pivot all fields into columns. This makes signal, bid, and ask
  // available in the same row, eliminating the need for a self-join.
  |> pivot(rowKey: ["_time", "strategy"], columnKey: ["_field"], valueColumn: "_value")
  // Now, calculate the current mid-price. We drop rows that might be missing a field.
  |> filter(fn: (r) => exists r.bid and exists r.ask and exists r.signal)
  |> map(fn: (r) => ({
      _time: r._time,
      strategy: r.strategy,
      signal: r.signal,
      current_mid: (r.bid + r.ask) / 2.0
    }))

// --- Step 2: Prepare a lightweight stream of FUTURE mid-prices ---
// This stream only processes bid and ask, making it much leaner.
futureMidData = from(bucket: "signals_db/default_signals_retention")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "StrategySignal")
  |> filter(fn: (r) => contains(value: r.strategy, set: ${Strategy:json}))
  // Only fetch bid and ask, we don't need 'signal' for the future price.
  |> filter(fn: (r) => r._field == "bid" or r._field == "ask")
  |> aggregateWindow(every: $__interval, fn: last, createEmpty: false)
  |> pivot(rowKey: ["_time", "strategy"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => exists r.bid and exists r.ask)
  |> map(fn: (r) => ({
      _time: r._time,
      strategy: r.strategy,
      // We are calculating the mid-price that will become the "future_mid"
      _value: (r.bid + r.ask) / 2.0
    }))
  // This is the magic: shift the timestamps of this data BACKWARDS by the walkahead duration.
  // This makes the future data's timestamp align with the current data's timestamp for the join.
  |> timeShift(duration: duration(v: "-${walkahead}"))
  // Rename the value to 'future_mid' for clarity in the join.
  |> rename(columns: {_value: "future_mid"})

// --- Step 3: Join the two streams and calculate the final result ---
// We now perform only ONE join operation.
result = join(
  tables: {current: currentData, future: futureMidData},
  on: ["_time", "strategy"]
)
  |> map(fn: (r) => {
      // The logic for calculating the difference based on signal direction
      signal_mid_diff = r.signal - r.current_mid

      return {
        _time: r._time,
        strategy: r.strategy,
        varad_walkahead: if r.future_mid == 0.0 or r.current_mid == 0.0 // Avoid division by zero or invalid data
                        then 0.0
                        else if signal_mid_diff > 0.0 
                              then r.future_mid - r.current_mid // Profit on long
                              else r.current_mid - r.future_mid // Profit on short
      }
  })
  // The rest of the query remains the same as it's efficient.
  |> group(columns: ["strategy"])
  |> cumulativeSum(columns: ["varad_walkahead"])
  |> set(key: "walkahead", value: "${walkahead}")

result
